from save_review import save
from pathlib import Path
import json
C={a['number']:a for a in json.loads((Path(__file__).parents[2]/'全书分段底稿.json').read_text())}
def rep(n,pairs):
 d={}
 for b in C[n]['blocks']:
  if b['language']=='en' or b['kind']=='image':continue
  v=b['text']
  for x,y in pairs:v=v.replace(x,y)
  if v!=b['text']:d[int(b['id'][-4:])]=v
 return d
save(1564,{2:'快速打击战舰指星际战士使用的小型护卫舰艇，负责巡逻领地，以及护卫较大的战斗驳船和打击巡洋舰。',4:'各战团保有的数量与舰型不同，常见型号包括帝国海军也使用的剑级、火风暴级护卫舰和眼镜蛇级驱逐舰，以及星际战士专用的猎手级驱逐舰、短剑级与新星级护卫舰。',6:'这类舰艇通常不搭载常规星际战士战斗部队，仅有一小组科技战士，协助操舰的战团农奴。'},notes={6:'原文先称没有星际战士，随后明确有科技战士；按无常规作战部队、仅配技术骨干的语义理解。cadre是一组骨干，非一人。'},terms=[('Rapid Strike Vessel','快速打击战舰'),('Adytum','内殿号'),('Amareo','阿玛雷奥号')])
d=rep(1565,[('爱森斯坦','艾森斯坦'),('伊克顿·克鲁兹','亚克顿·克鲁兹'),('伊格内修斯·格鲁戈尔','伊格纳修斯·格鲁戈尔')]);d.update({
2:'艾森斯坦号是荷鲁斯之乱爆发时发挥关键作用的帝国战舰。它载着忠诚派星际战士离开伊斯塔万星系，前往泰拉，向帝皇警告荷鲁斯的背叛。',7:'即使在叛乱时期，艾森斯坦号也已是一艘老舰。它长逾两公里，形似短剑级护卫舰，伊斯塔万三号事件发生时隶属死亡守卫。据舰长所说，“Eisenstein”在一种古地球语言中意为“铁石”，也是泰拉时代两位名人的姓氏：一位记述者，一位科学家。',
9:'伊斯塔万三号屠杀前不久，纳撒尼尔·伽罗与其连队被派驻艾森斯坦号。伽罗在近期一次交锋中负伤，因此未能随其他死亡守卫参加地面进攻。第一连长卡拉斯·提丰另将伊格纳修斯·格鲁戈尔的连队安排上舰，准备伺机除掉伽罗等人。与大多数阿斯塔特舰船一样，日常操舰由凡人舰员负责，舰长是巴里克·卡里亚。轰炸前，索尔·塔维茨先向艾森斯坦号示警，再飞向地面，试图警告其他忠诚派。伽罗据此搜查舰内，发现格鲁戈尔正在准备发射病毒炸弹。他出手阻止，混乱中一枚炸弹破裂，杀死格鲁戈尔及其部下。',
11:'艾森斯坦号即将跃入亚空间、前往泰拉报信之际，亚克顿·克鲁兹带着一群平民加入伽罗。他们是在加维尔·洛肯安排下，从荷鲁斯旗舰逃出来的。艾森斯坦号险险避过提丰座舰终焉号的炮火，逃离星系。',
13:'航途中，盖勒力场短暂失效，纳垢的力量使死去的星际战士复活。敌人势不可挡，伽罗只得下令紧急返回物质宇宙。受污染的战士随之消失，但骤然脱离亚空间的冲击超过导航者所能承受的限度，艾森斯坦号因此无法继续航行。伽罗命人抛出并引爆亚空间引擎，希望以爆炸向过往舰船求救。最终，帝国之拳的移动堡垒修道院山阵号救下幸存者，艾森斯坦号则被主动毁弃。',
15:'叛乱之后，艾森斯坦号留下了神秘传说，其状况仍不明。大裂隙形成后，有人声称多次目睹它重新出现。传言说，第七次现身时，莫塔里安本人将随之降临，带来毁灭。',19:'Racel Vought — Executive Officer',20:'瑞赛尔·沃特——副舰长',22:'提林·马斯——通讯官',
27:'艾森斯坦号最初出现于1988年为《战锤40,000》第一版出版的《混沌领域：黑暗之奴》，用于引入荷鲁斯之乱背景。书中一段文字写道，伊斯塔万三号遭生物武器轰炸时，忠诚的阿斯塔特军官与士兵发现荷鲁斯已被混沌污染，夺取名为艾森斯坦号的护卫舰。当荷鲁斯转向伊斯塔万五号时，他们驾舰逃离，向外界示警。',
29:'1989年的《星际战士》游戏是《史诗》体系的前身，以荷鲁斯之乱为背景。其叙事侧栏通过塔维茨、伽罗、瓦伦等连长的对话讲述艾森斯坦号。他们面对的选择是“背叛荷鲁斯，还是背叛帝皇”。这份早期设定称，荷鲁斯麾下有五个“战团”，内部引入了戴文的战士结社，原有圣典指挥体系受到忽视；多数军团战士转而效忠荷鲁斯与“蛮荒世界的神祇”。伊斯塔万（早期英文另拼Istvaan）的毁灭没有得到泰拉命令，病毒轰炸也没有正当依据。',
31:'这一版本并未提到忠诚派遭到屠杀。瓦伦说自己有15名吞世者，伽罗有12人；另两名未具名军官分别提到10名影月苍狼和20名千子。塔维茨则说，除自己之外还有9名帝皇之子。原叙述称总数为70人。他们决定由瓦伦夺取具备亚空间跃迁能力、但因机械故障而落后的艾森斯坦号，其余人放慢各自舰船，夺取另外四舰并掩护它突围，让瓦伦和吞世者将警讯带出去。',
32:'Canon Conflicts 正式设定之间的冲突',
55:'上述人数实际只合计69人。由于数字来自军官对话，可能有一名未具名军官把自己算入，另一名却没有。不过，瓦伦说70恰好等于五个军团番号之和；他并不可能知道这种计数口径差异。因此，条目认为这更可能是文字中的简单错误。',
57:'不同叙述还带来其他矛盾。例如，早期版本将审判庭放在帝皇仍活动的年代；加夫·索普后来为《审判官》游戏编写设定时，又将其成立时间改到帝皇升天之后。'},
)
